edits.newText:
async function showProject(id, error = '') {
  const response = await fetch(`/api/projects/${encodeURIComponent(id)}`);
  if (!response.ok) { app.innerHTML = '<h1>Project not found</h1><button class="back" type="button">Projects</button>'; }
  else {
    const project = await response.json();
    const tasksResponse = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`);
    const tasks = await tasksResponse.json();
    app.innerHTML = `<button class="back" type="button">Projects</button><h1>${escapeHtml(project.name)}</h1>
      ${error ? `<p role="alert">${escapeHtml(error)}</p>` : ''}
      <form id="task-form"><div class="field"><label for="task-title">Task title</label><input id="task-title" name="title" type="text"></div><button type="submit">Create task</button></form>
      <label for="task-filter">Task filter</label><select id="task-filter"><option>All</option><option>Open</option><option>Completed</option></select>
      <section aria-label="Tasks">${tasks.map(task => `<div class="row task-row" data-testid="task-row" data-completed="${task.completed}"><span>${escapeHtml(task.title)}</span><input type="checkbox" aria-label="Complete ${escapeHtml(task.title)}" data-task-id="${task.id}" ${task.completed ? 'checked' : ''}></div>`).join('')}</section>`;
    const filter = app.querySelector('#task-filter');
    filter.addEventListener('change', () => app.querySelectorAll('.task-row').forEach(row => {
      row.hidden = filter.value === 'Open' ? row.dataset.completed === 'true' : filter.value === 'Completed' ? row.dataset.completed !== 'true' : false;
    }));
    app.querySelector('#task-form').addEventListener('submit', async event => {
      event.preventDefault();
      const title = new FormData(event.currentTarget).get('title').trim();
      if (!title) return showProject(id, 'Task title is required');
      const created = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }) });
      if (!created.ok) return showProject(id, (await created.json()).error);
      showProject(id);
    });
    app.querySelectorAll('[data-task-id]').forEach(checkbox => checkbox.addEventListener('change', async () => {
      await fetch(`/api/tasks/${checkbox.dataset.taskId}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) });
      showProject(id);
    }));
  }
  app.querySelector('.back').addEventListener('click', () => { history.pushState({}, '', '/'); showList(); });
}

